public async Task ForwardAsync(ServiceBusReceivedMessage msg, ServiceBusSender sender) {
    var hops = HopList.Parse(msg.ApplicationProperties);      // from the "history" JSON string
    hops.Add(new Hop(nameof(OrderValidator), DateTimeOffset.UtcNow));
    var next = new ServiceBusMessage(msg.Body) {
        ApplicationProperties = { ["history"] = hops.ToJson() }   // strings only
    };
    await sender.SendMessageAsync(next);
}
